def solve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)
    best_score = None
    best_versions = None

    requirements = {name: [tuple(bounds)] for name, bounds in roots.items()}

    def candidates(name, constraints):
        if name not in packages:
            return []
        forbidden = blocked.get(name, [])
        pin = pins.get(name)
        result = []
        for row in packages[name]:
            version = row["version"]
            if any(version < low or version > high for low, high in constraints):
                continue
            if version in forbidden or (name in pins and version != pin):
                continue
            result.append(row)
        return sorted(result, key=lambda row: row["version"], reverse=True)

    def search(assignments, constraints):
        nonlocal best_score, best_versions

        required = set(constraints)
        for name, row in assignments.items():
            if row not in candidates(name, constraints.get(name, [])):
                return

        pending = [name for name in required if name not in assignments]
        if not pending:
            versions = {name: row["version"] for name, row in assignments.items()}
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = versions
            return

        # Choosing the smallest current domain reduces branching; every branch
        # is still explored so the final result is lexicographically maximal.
        domains = [(candidates(name, constraints[name]), name) for name in pending]
        domain, name = min(domains, key=lambda item: (len(item[0]), item[1]))
        for row in domain:
            next_assignments = dict(assignments)
            next_assignments[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True
            for dep in active_dependencies(row, features):
                target = dep["name"]
                next_constraints.setdefault(target, []).append((dep["min"], dep["max"]))
                if target not in packages:
                    valid = False
                    break
            if valid:
                search(next_assignments, next_constraints)

    if all(name in packages for name in roots):
        search({}, requirements)

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
